import React, { useEffect, useState } from "react"
import { Link } from "gatsby"
import dayjs from "dayjs"
import { getPublicMemos } from "../../api/memos"
import { MemoListItemDto } from "../../types/dto"
import { shouldHideThinkOnDomain } from "../../utils/domain"
import { Reveal } from "../animations"

const MAX_LEN = 60

function truncate(text: string): string {
  const clean = text.replace(/\s+/g, " ").trim()
  return clean.length > MAX_LEN ? `${clean.slice(0, MAX_LEN)}…` : clean
}

/**
 * 碎片 pull-quote：最新一条碎片的大号衬线引言，与主题河流同页并排。
 * 无数据/加载失败/域名隐藏时整体不渲染（连 Reveal 外壳一起消失，河流自动占满整行）。
 */
function PullQuote(): React.ReactElement | null {
  const [memo, setMemo] = useState<MemoListItemDto | null>(null)

  useEffect(() => {
    if (shouldHideThinkOnDomain(window.location.hostname)) {
      return
    }
    let cancelled = false
    getPublicMemos({ page: 1, limit: 1, sortBy: "createdAt", sortOrder: "desc" })
      .then((res) => {
        if (!cancelled) setMemo(res.items?.[0] ?? null)
      })
      .catch(() => {
        // 失败保持 null，整栏消失
      })
    return () => {
      cancelled = true
    }
  }, [])

  if (!memo) return null

  return (
    <Reveal delay={1} className="lg:flex-4">
      <aside>
        <blockquote className="border-l-2 border-accent pl-6 sm:pl-7 font-serif text-lg sm:text-xl font-semibold leading-[1.9] text-foreground">
          {truncate(memo.content)}
        </blockquote>
        <div className="mt-4 pl-6 sm:pl-7 text-xs text-foreground-subtle tabular-nums">
          碎片 · {dayjs(memo.createdAt).format("MM-DD")} ·{" "}
          <Link to="/think/" className="link-underline text-accent">
            更多碎片 →
          </Link>
        </div>
      </aside>
    </Reveal>
  )
}

export default PullQuote
