import React, { useEffect, useState } from "react"
import { Link } from "gatsby"
import { GatsbyImage } from "gatsby-plugin-image"
import dayjs from "dayjs"
import { getPublicMemos } from "../../api/memos"
import { shouldHideThinkOnDomain } from "../../utils/domain"
import { photoHash } from "../photos"
import type { PhotoItem } from "../photos"

/** 构建期由 index.tsx 归一化好的 blog payload */
export interface FeedBlogPayload {
  slug: string
  title: string
  /** 缩略内容：frontmatter description，缺失时回退正文摘要 */
  summary?: string
}

/** think（碎片）客户端插入项的 payload；不展示附件 */
interface FeedThinkPayload {
  memoId: string
  content: string
}

/**
 * 统一时间线条目。ts 为排序键（epoch ms）：blog/photo 取日期当天 0 点，
 * think 取 createdAt 原值（epoch ms）；dateLabel 已格式化为 YYYY.MM.DD。
 */
export type FeedItem =
  | { type: "blog"; ts: number; dateLabel: string; payload: FeedBlogPayload }
  | { type: "photo"; ts: number; dateLabel: string; payload: PhotoItem }
  | { type: "think"; ts: number; dateLabel: string; payload: FeedThinkPayload }

const THINK_LIMIT = 5
const FEED_MAX = 12

const feedKey = (item: FeedItem): string => {
  switch (item.type) {
    case "blog":
      return `blog:${item.payload.slug}`
    case "photo":
      return `photo:${item.payload.slug}`
    case "think":
      return `think:${item.payload.memoId}`
  }
}

/** Blog 条目：eyebrow（胶囊 + 日期）+ 超大衬线标题 + 缩略内容；isHero 用最大字号 */
function FeedBlogItem({
  item,
  isHero,
}: {
  item: Extract<FeedItem, { type: "blog" }>
  isHero: boolean
}): React.ReactElement {
  const { slug, title, summary } = item.payload
  return (
    <Link to={slug} className="group block py-6 sm:py-8">
      <div className="mb-3 flex items-baseline gap-3">
        <span className="rounded-full bg-accent-subtle px-2.5 py-0.5 text-[11px] font-semibold text-accent">
          文章
        </span>
        <span className="text-xs text-foreground-subtle tabular-nums">
          {item.dateLabel}
        </span>
      </div>
      {/* 不加 max-w / text-balance：一行放得下的标题不许提前换行 */}
      <h3
        className={`font-serif font-bold text-foreground transition-colors duration-200 group-hover:text-accent ${
          isHero
            ? "text-3xl sm:text-4xl leading-snug"
            : "text-xl sm:text-2xl leading-snug"
        }`}
      >
        {title}
      </h3>
      {summary && (
        <p
          className={`mt-3 max-w-2xl leading-relaxed text-foreground-secondary line-clamp-2 ${
            isHero ? "text-sm sm:text-[15px]" : "text-sm"
          }`}
        >
          {summary}
        </p>
      )}
    </Link>
  )
}

/** Photo 条目：满宽 16/9 图块，左下角图上题字「标题 — 日期」，深链 /photos/ lightbox */
function FeedPhotoItem({
  item,
}: {
  item: Extract<FeedItem, { type: "photo" }>
}): React.ReactElement {
  const photo = item.payload
  return (
    <div className="py-6 sm:py-8">
      <Link
        to={`/photos/${photoHash(photo.slug, photo.coverIndex)}`}
        aria-label={`查看照片「${photo.title}」`}
        className="group relative block overflow-hidden rounded-[3px]"
      >
        <GatsbyImage
          image={photo.cover}
          alt={photo.title}
          className="aspect-video w-full transition-transform duration-500 group-hover:scale-[1.02] motion-reduce:transition-none motion-reduce:scale-none"
          imgStyle={{ objectFit: "cover" }}
        />
        <div className="pointer-events-none absolute bottom-3 left-4 font-serif text-sm sm:text-base font-bold text-white [text-shadow:0_1px_6px_rgba(0,0,0,0.55)]">
          {photo.title} — {item.dateLabel}
        </div>
      </Link>
    </div>
  )
}

/** Think 条目：bg-secondary 整宽色块 + 斜体衬线引文，accent 色「」包角，整块跳 /think/ */
function FeedThinkItem({
  item,
}: {
  item: Extract<FeedItem, { type: "think" }>
}): React.ReactElement {
  return (
    <div className="py-6 sm:py-8">
      {/* bg-background-secondary 与页面背景只隔一个色阶，按设计原则配 shadow-xs */}
      <Link
        to="/think/"
        className="group block rounded-[3px] bg-background-secondary px-5 py-5 shadow-xs sm:px-7 sm:py-6"
      >
        <blockquote className="font-serif italic text-base sm:text-lg leading-relaxed text-foreground line-clamp-3">
          <span className="not-italic text-accent">「</span>
          {item.payload.content}
          <span className="not-italic text-accent">」</span>
        </blockquote>
        <div className="mt-3 text-xs text-foreground-subtle tabular-nums">
          碎片 · {item.dateLabel}
        </div>
      </Link>
    </div>
  )
}

interface LatestFeedProps {
  /** 构建期合并好的 blog+photo 时间线（已按 ts 倒序、已截前 10 条） */
  items: FeedItem[]
}

/**
 * 「03 最新」混排时间线：首屏即渲染完整 blog+photo（SEO 友好），
 * think 在 hydrate 后由 getPublicMemos 拉取插入。
 */
function LatestFeed({ items: initialItems }: LatestFeedProps): React.ReactElement {
  const [items, setItems] = useState<FeedItem[]>(initialItems)
  const [thinkEntered, setThinkEntered] = useState(false)

  useEffect(() => {
    // 与 PullQuote/Header 一致：aimo.plus 域名下不出现 think 内容
    if (shouldHideThinkOnDomain(window.location.hostname)) return
    let cancelled = false
    getPublicMemos({
      page: 1,
      limit: THINK_LIMIT,
      sortBy: "createdAt",
      sortOrder: "desc",
    })
      .then((res) => {
        if (cancelled) return
        const thinkItems: FeedItem[] = (res.items ?? []).map((m) => ({
          type: "think",
          ts: m.createdAt,
          dateLabel: dayjs(m.createdAt).format("YYYY.MM.DD"),
          payload: { memoId: m.memoId, content: m.content },
        }))
        if (thinkItems.length === 0) return
        setItems((prev) =>
          [...prev, ...thinkItems]
            .sort((a, b) => b.ts - a.ts)
            .slice(0, FEED_MAX)
        )
        // 下一帧再置位，触发一次性淡入；motion-reduce 禁掉 transition 即瞬时显示
        requestAnimationFrame(() => {
          if (!cancelled) setThinkEntered(true)
        })
      })
      .catch(() => {
        // 失败静默：保持 blog+photo 版本，无错误 UI
      })
    return () => {
      cancelled = true
    }
  }, [])

  // 时间线里第一篇 blog 用 hero 字号（think 插入不改变它是哪一篇）
  const firstBlog = items.find((i) => i.type === "blog")
  const heroKey = firstBlog ? feedKey(firstBlog) : null

  return (
    // 只保留底部 border：顶部已有 SectionHeading 的 border-b，再叠 border-t 会出现双线
    <div className="divide-y divide-hairline border-b border-hairline">
      {items.map((item) => {
        const thinkFade =
          item.type === "think"
            ? `transition-opacity duration-700 motion-reduce:transition-none ${
                thinkEntered ? "opacity-100" : "opacity-0"
              }`
            : undefined
        return (
          <div key={feedKey(item)} className={thinkFade}>
            {item.type === "blog" && (
              <FeedBlogItem item={item} isHero={feedKey(item) === heroKey} />
            )}
            {item.type === "photo" && <FeedPhotoItem item={item} />}
            {item.type === "think" && <FeedThinkItem item={item} />}
          </div>
        )
      })}
    </div>
  )
}

export default LatestFeed
