import React from "react"
import { graphql, Link, navigate, PageProps } from "gatsby"
import { GatsbyImage } from "gatsby-plugin-image"
import dayjs from "dayjs"
import Layout from "../components/layout"
import SEO from "../components/seo"
import { Reveal } from "../components/animations"
import {
  PullQuote,
  TopicRiver,
  WritingFootprint,
  LatestFeed,
} from "../components/home"
import type { RiverData, FeedItem } from "../components/home"
import { PhotoSpread } from "../components/photos"
import { toPhotoItem, isHomePhotoPosition, photoHash } from "../components/photos"
import type {
  HomePhotoPosition,
  PhotoItem,
  PhotoNode,
} from "../components/photos"

interface PostNode {
  node: {
    excerpt: string
    fields: {
      slug: string
    }
    frontmatter: {
      dateISO: string
      dateShort: string
      title: string
      description?: string
    }
  }
}

interface IndexPageData {
  site: {
    siteMetadata: {
      title: string
    }
  }
  allMarkdownRemark: {
    edges: PostNode[]
  }
  // 封面「最近更新」：仅博客文章（不含照片帖），与 03 最新分开取数
  latestBlog: {
    edges: {
      node: {
        fields: { slug: string }
        frontmatter: { dateShort: string; title: string }
      }
    }[]
  }
  now: {
    nodes: {
      frontmatter: {
        writing?: string
        reading?: string
        hacking?: string
        updated?: string
      }
    }[]
  }
  photos: {
    nodes: PhotoNode[]
  }
  feedPhotos: {
    nodes: PhotoNode[]
  }
}

interface FootprintCell {
  ym: string
  count: number
  titles: string[] // 当月文章标题，最多 6 篇
}

interface SeriesHighlight {
  id: string
  title: string
  count: number
  latestTitle: string | null
  latestSlug: string | null
}

// 全量文章的聚合数据，由 gatsby-node.ts onCreatePage 在构建期算好注入，
// 页面查询只拉最新 10 篇，page-data.json 不随文章总量膨胀
interface HomeAggregates {
  footprint: FootprintCell[]
  river: RiverData
  series: SeriesHighlight[] // 日就月将专题栏：按篇数降序前 5 个系列
  totalPosts: number
  totalYears: number
  totalTags: number
  allSlugs: string[] // 全部已发布博文 slug，供「随便逛逛」随机跳转
}

interface IndexPageContext {
  homeAggregates?: HomeAggregates
}

// 杂志式区块刊头：编号 + 衬线标题 + 右侧 meta，底部 hairline 分隔
function SectionHeading({
  index,
  title,
  meta,
}: {
  index?: string
  title: string
  meta?: React.ReactNode
}): React.ReactElement {
  return (
    <div className="mb-6 flex items-baseline justify-between gap-4 border-b border-hairline pb-4">
      <div className="flex items-baseline gap-3">
        {index && (
          <span className="text-xs tabular-nums text-foreground-subtle">
            {index}
          </span>
        )}
        <h2 className="font-serif text-xl sm:text-2xl font-bold text-foreground">
          {title}
        </h2>
      </div>
      {meta}
    </div>
  )
}

// eyebrow 小标签：编辑排版里的栏目前缀
function Eyebrow({ children }: { children: React.ReactNode }): React.ReactElement {
  return (
    <div className="mb-3 text-[11px] font-semibold uppercase tracking-[0.18em] text-accent">
      {children}
    </div>
  )
}

const BlogIndex: React.FC<PageProps<IndexPageData, IndexPageContext>> = ({
  data,
  pageContext,
  location,
}) => {
  const siteTitle = data.site.siteMetadata.title
  // 页面查询已 limit 10，即最新文章列表
  const latestPosts = data.allMarkdownRemark.edges
  const aggregates = pageContext.homeAggregates ?? {
    footprint: [],
    river: { years: [], bands: [], counts: [] },
    series: [],
    totalPosts: latestPosts.length,
    totalYears: 0,
    totalTags: 0,
    allSlugs: [],
  }
  const now = data.now?.nodes?.[0]
  // 首页照片选图：position 钉位优先，未钉的坑位由 featured 候选池
  // （相册级 featured 或图片级 featured/position）按 date 倒序回填
  const photoPool: PhotoItem[] = (data.photos?.nodes ?? [])
    .map(toPhotoItem)
    .filter((p): p is PhotoItem => p !== null)
  const pinned = new Map<HomePhotoPosition, PhotoItem>()
  for (const p of photoPool) {
    if (p.position && isHomePhotoPosition(p.position) && !pinned.has(p.position)) {
      pinned.set(p.position, p)
    }
  }
  const unpinned = photoPool.filter(
    (p) => ![...pinned.values()].some((q) => q.slug === p.slug)
  )
  const coverPhoto = pinned.get("cover") ?? unpinned[3] ?? unpinned[0] ?? null
  // 依次取散页坑位：钉位的直接用，否则从候选池取未占用的第一张
  const usedSlugs = new Set<string>(
    coverPhoto ? [coverPhoto.slug] : []
  )
  const takeSlot = (pos: HomePhotoPosition): PhotoItem | null => {
    const hit = pinned.get(pos) ?? unpinned.find((p) => !usedSlugs.has(p.slug)) ?? null
    if (hit) usedSlugs.add(hit.slug)
    return hit
  }
  const spreadPhotos = [takeSlot("lead"), takeSlot("side-1"), takeSlot("side-2")].filter(
    (p): p is PhotoItem => p !== null
  )
  // 03 最新：blog + photo 合并为统一时间线（ts 归一化为 epoch ms），
  // 倒序取前 10；think 由 LatestFeed 在客户端插入
  const blogItems: FeedItem[] = latestPosts.map(({ node }) => ({
    type: "blog",
    ts: dayjs(node.frontmatter.dateISO).valueOf(),
    dateLabel: node.frontmatter.dateShort,
    payload: {
      slug: node.fields.slug,
      title: node.frontmatter.title || node.fields.slug,
      // 缩略内容：优先 frontmatter .description，缺失时回退正文摘要
      summary: node.frontmatter.description ?? node.excerpt,
    },
  }))
  const photoItems: FeedItem[] = (data.feedPhotos?.nodes ?? [])
    .map(toPhotoItem)
    .filter(
      (p): p is PhotoItem & { date: string } =>
        p !== null && typeof p.date === "string"
    )
    .map((p) => ({
      type: "photo",
      ts: dayjs(p.date).valueOf(),
      dateLabel: dayjs(p.date).format("YYYY.MM.DD"),
      payload: p,
    }))
  const feedItems: FeedItem[] = [...blogItems, ...photoItems]
    .sort((a, b) => b.ts - a.ts)
    .slice(0, 10)

  const nowRows = [
    { label: "在写", text: now?.frontmatter?.writing },
    { label: "在读", text: now?.frontmatter?.reading },
    { label: "在折腾", text: now?.frontmatter?.hacking },
  ].filter((r): r is { label: string; text: string } => Boolean(r.text))

  return (
    <Layout location={location} title={siteTitle}>
      <SEO
        title="首页"
        keywords={[`blog`, `gatsby`, `javascript`, `react`]}
      />

      {latestPosts.length === 0 ? (
        <div className="py-16 text-center fade-in">
          <h3 className="font-serif text-xl font-medium text-foreground mb-2">
            暂无文章
          </h3>
          <p className="text-sm text-foreground-muted">
            精彩内容正在筹备中，敬请期待...
          </p>
        </div>
      ) : (
        <>
          {/* 封面跨页：刊头 + 此刻（编者的话）+ 竖幅照片 */}
          <Reveal className="mb-16 sm:mb-24">
            <div className="grid gap-10 lg:grid-cols-12 lg:gap-14">
              <div className="lg:col-span-7 lg:flex lg:flex-col">
                {/* 刊名已在 Header 刊头；保留视觉隐藏 h1 维持文档大纲 */}
                <h1 className="sr-only">一席之地</h1>
                {/* 刊首语：陆游句，扣「拆源码、手写实现」的工程师躬行气质 */}
                <figure>
                  <blockquote className="font-serif text-base sm:text-lg leading-loose text-foreground-secondary">
                    纸上得来终觉浅，绝知此事要躬行。
                  </blockquote>
                  <figcaption className="mt-2 text-xs text-foreground-subtle">
                    —— 陆游《冬夜读书示子聿》
                  </figcaption>
                </figure>
                {/* 封面导读：杂志 cover lines，预告最新三篇 */}
                <div className="mt-8">
                  <div className="mb-3 flex items-baseline justify-between gap-4">
                    <span className="text-[11px] font-semibold uppercase tracking-[0.18em] text-accent">
                      最近更新 · Latest
                    </span>
                    <Link
                      to="/blog/"
                      className="link-underline text-xs text-accent"
                    >
                      查看更多 →
                    </Link>
                  </div>
                  <ol className="divide-y divide-hairline border-t border-b border-hairline">
                    {data.latestBlog.edges.map(({ node }) => (
                      <li key={node.fields.slug}>
                        <Link
                          to={node.fields.slug}
                          className="group flex items-baseline gap-4 py-2.5 text-sm"
                        >
                          <span className="w-18 shrink-0 text-xs text-foreground-subtle tabular-nums">
                            {node.frontmatter.dateShort}
                          </span>
                          <span className="truncate font-serif text-foreground transition-colors duration-200 group-hover:text-accent">
                            {node.frontmatter.title || node.fields.slug}
                          </span>
                        </Link>
                      </li>
                    ))}
                  </ol>
                </div>
                {nowRows.length > 0 && (
                  <div className="mt-10 lg:mt-auto lg:pt-10">
                    <Eyebrow>此刻 · Now</Eyebrow>
                    <div className="divide-y divide-hairline border-t border-b border-hairline">
                      {nowRows.map((r) => (
                        <div
                          key={r.label}
                          className="flex items-baseline gap-5 py-2.5 text-sm"
                        >
                          <span className="w-11 shrink-0 text-xs text-foreground-subtle">
                            {r.label}
                          </span>
                          <span className="truncate text-foreground">
                            {r.text}
                          </span>
                        </div>
                      ))}
                    </div>
                    {now?.frontmatter?.updated && (
                      <p className="mt-2 text-right text-[11px] text-foreground-subtle tabular-nums">
                        更新于 {now.frontmatter.updated}
                      </p>
                    )}
                  </div>
                )}
              </div>
              {coverPhoto && (
                <figure className="max-w-sm lg:max-w-none lg:col-span-5">
                  <Link
                    to={`/photos/${photoHash(coverPhoto.slug, coverPhoto.coverIndex)}`}
                    aria-label={`查看照片「${coverPhoto.title}」及更多照片`}
                    className="group block overflow-hidden rounded-[3px]"
                  >
                    <GatsbyImage
                      image={coverPhoto.cover}
                      alt={coverPhoto.title}
                      className="aspect-4/5 w-full transition-transform duration-500 group-hover:scale-[1.02] motion-reduce:transition-none motion-reduce:scale-none"
                      imgStyle={{ objectFit: "cover" }}
                    />
                  </Link>
                  <figcaption className="mt-2 flex items-baseline justify-between gap-3">
                    <span className="shrink-0 font-serif text-sm text-foreground">
                      {coverPhoto.title}
                    </span>
                    {coverPhoto.note && (
                      <span className="truncate text-xs text-foreground-subtle">
                        {coverPhoto.note}
                      </span>
                    )}
                  </figcaption>
                </figure>
              )}
            </div>
          </Reveal>

          {/* 01 日就月将：热力图 + 专题栏（《诗经·周颂·敬之》「日就月将」，日积月累之意） */}
          <Reveal className="mb-16 sm:mb-24">
            <section>
              <SectionHeading
                index="01"
                title="日就月将"
                meta={
                  <span className="text-xs text-foreground-subtle tabular-nums">
                    {aggregates.totalPosts} 篇 · {aggregates.totalYears} 年
                  </span>
                }
              />
              <div className="flex flex-col gap-8 lg:flex-row lg:gap-10">
                <div className="shrink-0">
                  <WritingFootprint
                    data={aggregates.footprint}
                    totalPosts={aggregates.totalPosts}
                    totalYears={aggregates.totalYears}
                    totalTags={aggregates.totalTags}
                  />
                </div>
                {aggregates.series.length > 0 && (
                  <aside className="min-w-0 flex-1 flex flex-col lg:border-l border-hairline lg:pl-10">
                    <div className="mb-3 flex items-baseline justify-between gap-4">
                      <span className="text-[11px] font-semibold uppercase tracking-[0.18em] text-accent">
                        专题 · Series
                      </span>
                      <Link
                        to="/series/"
                        className="link-underline text-xs text-accent"
                      >
                        全部专题 →
                      </Link>
                    </div>
                    <div>
                      {aggregates.series.map((s) => (
                        <Link
                          key={s.id}
                          to={`/series/${s.id}/`}
                          className="group block border-b border-hairline py-2.5 last:border-b-0"
                        >
                          <div className="flex items-baseline justify-between gap-3">
                            <span className="font-serif text-[15px] font-bold text-foreground transition-colors duration-200 group-hover:text-accent">
                              {s.title}
                            </span>
                            <span className="shrink-0 text-[11px] text-foreground-subtle tabular-nums">
                              {s.count} 篇
                            </span>
                          </div>
                          {s.latestTitle && (
                            <div className="mt-0.5 truncate text-xs text-foreground-muted">
                              最新 · {s.latestTitle}
                            </div>
                          )}
                        </Link>
                      ))}
                    </div>
                  </aside>
                )}
              </div>
            </section>
          </Reveal>

          {/* 02 主题河流：河流图 + 碎片 pull-quote 并排 */}
          <Reveal className="mb-16 sm:mb-24">
            <section>
              <SectionHeading
                index="02"
                title="主题河流"
                meta={
                  <Link
                    to="/tags/"
                    className="link-underline text-xs text-accent"
                  >
                    全部主题 →
                  </Link>
                }
              />
              <div className="flex flex-col gap-10 lg:flex-row lg:items-center">
                <div className="min-w-0 lg:flex-8">
                  <TopicRiver river={aggregates.river} />
                </div>
                {/* 碎片栏的 Reveal 包装收在 PullQuote 内部：无数据/域名隐藏时整栏消失，河流自动占满整行 */}
                <PullQuote />
              </div>
            </section>
          </Reveal>

          {/* 照片散页：数据区之后的图片呼吸页，无 featured 时整段不渲染 */}
          {spreadPhotos.length > 0 && (
            <Reveal className="mb-16 sm:mb-24">
              <PhotoSpread photos={spreadPhotos} />
            </Reveal>
          )}

          {/* 03 最新：photo / blog / think 超大字刊目混排 */}
          <section>
            <SectionHeading
              index="03"
              title="最新"
              meta={
                <div className="flex items-center gap-4">
                  {aggregates.allSlugs.length > 0 && (
                    <button
                      type="button"
                      className="link-underline text-xs text-accent"
                      onClick={() => {
                        const slugs = aggregates.allSlugs
                        navigate(
                          slugs[Math.floor(Math.random() * slugs.length)]
                        )
                      }}
                    >
                      随便逛逛
                    </button>
                  )}
                  <Link
                    to="/blog/"
                    className="link-underline text-xs text-accent"
                  >
                    全部文章 →
                  </Link>
                </div>
              }
            />

            <Reveal>
              <LatestFeed items={feedItems} />
            </Reveal>
          </section>
        </>
      )}
    </Layout>
  )
}

export default BlogIndex

export const pageQuery = graphql`
  query {
    site {
      siteMetadata {
        title
      }
    }
    allMarkdownRemark(
      sort: { frontmatter: { date: DESC } }
      filter: {
        frontmatter: { published: { ne: false } }
        fileAbsolutePath: { regex: "/content/blog/" }
      }
      limit: 10
    ) {
      edges {
        node {
          excerpt
          fields {
            slug
          }
          frontmatter {
            dateISO: date(formatString: "YYYY-MM-DD")
            dateShort: date(formatString: "YYYY.MM.DD")
            title
            description
          }
        }
      }
    }
    now: allMarkdownRemark(
      filter: { fileAbsolutePath: { regex: "/content/now/" } }
      limit: 1
    ) {
      nodes {
        frontmatter {
          writing
          reading
          hacking
          updated(formatString: "YYYY-MM-DD")
        }
      }
    }
    latestBlog: allMarkdownRemark(
      sort: { frontmatter: { date: DESC } }
      filter: {
        frontmatter: { published: { ne: false } }
        fileAbsolutePath: { regex: "/content/blog/" }
      }
      limit: 5
    ) {
      edges {
        node {
          fields {
            slug
          }
          frontmatter {
            dateShort: date(formatString: "YYYY.MM.DD")
            title
          }
        }
      }
    }
    photos: allMarkdownRemark(
      sort: { frontmatter: { date: DESC } }
      filter: {
        fileAbsolutePath: { regex: "/content/photos/" }
        fields: { homePhotoEligible: { eq: true } }
      }
      limit: 12
    ) {
      nodes {
        frontmatter {
          title
          note
          photos {
            src {
              childImageSharp {
                gatsbyImageData(
                  width: 1200
                  placeholder: BLURRED
                  formats: [AUTO, WEBP]
                )
              }
            }
            note
            featured
            position
          }
        }
        parent {
          ... on File {
            relativeDirectory
          }
        }
      }
    }
    feedPhotos: allMarkdownRemark(
      sort: { frontmatter: { date: DESC } }
      filter: { fileAbsolutePath: { regex: "/content/photos/" } }
      limit: 6
    ) {
      nodes {
        frontmatter {
          title
          note
          date(formatString: "YYYY-MM-DD")
          photos {
            src {
              childImageSharp {
                gatsbyImageData(
                  width: 1200
                  placeholder: BLURRED
                  formats: [AUTO, WEBP]
                )
              }
            }
            note
            featured
            position
          }
        }
        parent {
          ... on File {
            relativeDirectory
          }
        }
      }
    }
  }
`
