import React from "react"
import { Link } from "gatsby"

interface FootprintCell {
  ym: string
  count: number
  titles: string[]
}

interface WritingFootprintProps {
  data: FootprintCell[]
  totalPosts: number
  totalYears: number
  totalTags: number
}

const MONTHS = Array.from({ length: 12 }, (_, i) => i + 1)

// 4 档密度阶梯，使用 --heat-* 固定色值（明暗主题各自定义，浅色为逐档加深的绿）
const LEVEL_CLASSES = [
  "bg-background-secondary",
  "bg-heat-1",
  "bg-heat-2",
  "bg-heat-3",
  "bg-heat-4",
]

function WritingFootprint({
  data,
  totalPosts,
  totalYears,
  totalTags,
}: WritingFootprintProps): React.ReactElement {
  const [tip, setTip] = React.useState<{
    ym: string
    count: number
    titles: string[]
    x: number
    y: number
  } | null>(null)

  const cellByYm = new Map(data.map((d) => [d.ym, d]))
  const maxCount = Math.max(1, ...data.map((d) => d.count))

  const currentYear = new Date().getFullYear()
  const earliestYear = Math.min(
    2015,
    ...data.map((d) => Number(d.ym.slice(0, 4))).filter((y) => y > 0)
  )
  const years = Array.from(
    { length: currentYear - earliestYear + 1 },
    (_, i) => currentYear - i
  )

  const levelOf = (count: number): number =>
    count === 0 ? 0 : Math.min(4, Math.ceil((count / maxCount) * 4))

  const stats: { value: number; label: string }[] = [
    { value: totalPosts, label: "篇文章" },
    { value: totalYears, label: "年 · 笔耕不辍" },
    { value: totalTags, label: "个主题" },
  ]

  return (
    <div className="relative flex flex-col gap-4 sm:flex-row sm:gap-8">
      {/* 统计栏：移动端横排置顶，桌面端收窄为左侧竖排 */}
      <div className="flex shrink-0 divide-x divide-hairline sm:w-32 sm:flex-col sm:justify-center sm:gap-5 sm:divide-x-0">
        {stats.map((s) => (
          <div key={s.label} className="flex-1 text-center sm:text-left">
            <div className="font-serif text-lg sm:text-2xl font-bold text-foreground tabular-nums">
              {s.value}
            </div>
            <div className="mt-1 text-xs text-foreground-muted">{s.label}</div>
          </div>
        ))}
      </div>

      {/* 热力图：小方块保持 GitHub 式密度；行末不再放年度条，
          右侧宽度让给 index.tsx 的专题栏 */}
      <div className="min-w-0 flex flex-col gap-[3px]">
        {/* 月份表头 */}
        <div className="flex items-center gap-[3px]">
          <span className="w-9 shrink-0" />
          {MONTHS.map((m) => (
            <span
              key={m}
              className="w-[18px] sm:w-[22px] shrink-0 text-center text-[9px] text-foreground-subtle"
            >
              {m}
            </span>
          ))}
        </div>

        {/* 年份行 */}
        {years.map((year) => (
          <div key={year} className="flex items-center gap-[3px]">
            <span className="w-9 shrink-0 text-xs text-foreground-muted tabular-nums">
              {year}
            </span>
            {MONTHS.map((month) => {
              const ym = `${year}-${String(month).padStart(2, "0")}`
              const cell = cellByYm.get(ym)
              const count = cell?.count ?? 0
              // min-h/w-0：豁免移动端 a/button 44px 触控下限的全局规则，
              // 否则格子被撑成 44px 方块横向溢出（热力图是密集数据格，豁免可接受）
              const cellClassName = `h-[18px] w-[18px] sm:h-[22px] sm:w-[22px] shrink-0 min-h-0 min-w-0 rounded-[3px] transition-opacity ${
                LEVEL_CLASSES[levelOf(count)]
              }`

              const showTip = (e: React.SyntheticEvent) => {
                const el = e.currentTarget as HTMLElement
                setTip({
                  ym,
                  count,
                  titles: cell?.titles ?? [],
                  x: el.offsetLeft + el.offsetWidth / 2,
                  y: el.offsetTop,
                })
              }

              return count > 0 ? (
                <Link
                  key={ym}
                  to={`/blog#m-${ym}`}
                  aria-label={`${ym} 发布 ${count} 篇文章，查看该月文章`}
                  className={`${cellClassName} cursor-pointer hover:opacity-75 focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent`}
                  onMouseEnter={showTip}
                  onMouseLeave={() => setTip(null)}
                  onFocus={showTip}
                  onBlur={() => setTip(null)}
                />
              ) : (
                <span
                  key={ym}
                  className={cellClassName}
                  onMouseEnter={showTip}
                  onMouseLeave={() => setTip(null)}
                  onFocus={showTip}
                  onBlur={() => setTip(null)}
                />
              )
            })}
          </div>
        ))}
      </div>

      {/* 悬浮详情卡：定位基于外层 relative 容器，向上弹出 */}
      {tip && (
        <div
          className="pointer-events-none absolute z-10 w-max max-w-[220px] -translate-x-1/2 -translate-y-full rounded-md bg-background-card px-3 py-2 text-xs text-foreground shadow-lg"
          style={{ left: tip.x, top: tip.y - 6 }}
        >
          <div className="font-medium tabular-nums">
            {tip.ym} · {tip.count} 篇
          </div>
          {tip.titles.length > 0 && (
            <ul className="mt-1 space-y-0.5 text-foreground-muted">
              {tip.titles.slice(0, 3).map((t) => (
                <li key={t} className="truncate">
                  {t}
                </li>
              ))}
              {tip.count > 3 && <li>…</li>}
            </ul>
          )}
        </div>
      )}
    </div>
  )
}

export default WritingFootprint
